mapper.select:
select id, name, title, pid, menu_id menuId
from sys_permission
where deleted = 0;

select m.id from sys_menu m where m.deleted = 0 and m.id in
#{id}
and not exists (select 1 from sys_permission p where p.menu_id = m.id and p.deleted = 0) order by m.id

select menu_id menuId, min(id) permissionId from sys_permission where deleted = 0 and menu_id in
#{id}
group by menu_id
